#!/usr/bin/env tsx
/**
 * Generates vendor/openreply/.env from the single root .env — so you
 * only ever hand-edit one file. Next.js only auto-loads env files
 * from its own project directory, which is why OpenReply needs its
 * own physical .env; this script is what keeps that from being a
 * second file you maintain by hand.
 *
 * Re-run any time you change an OPENREPLY_* or shared META_* value in
 * the root .env. The generated file has a header saying not to edit
 * it directly.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { parse } from "dotenv";

const rootEnvPath = resolve(process.cwd(), ".env");
if (!existsSync(rootEnvPath)) {
  console.error(`No .env found at ${rootEnvPath}. Copy .env.example to .env and fill it in first.`);
  process.exit(1);
}

const root = parse(readFileSync(rootEnvPath, "utf-8"));

function required(key: string): string {
  const value = root[key];
  if (!value) {
    console.error(`Missing ${key} in .env — fill it in, then re-run this script.`);
    process.exit(1);
  }
  return value;
}

function optional(key: string, fallback = ""): string {
  return root[key] || fallback;
}

const port = optional("OPENREPLY_PORT", "3100");
// Plain DATABASE_URL, same `public` schema as our own tables — NOT an
// isolated `openreply` schema. That was tried and reverted: Prisma's query
// ENGINE (not just the CLI) hardcodes `public.` on every generated query
// unless the schema is declared inside schema.prisma itself via a
// `schemas = [...]` datasource config + `@@schema()` on every model
// (Prisma's multiSchema feature) — no connection-string trick fixes this
// from the outside, since it's baked into query generation, not connection
// routing. Editing vendor/openreply/prisma/schema.prisma to add that would
// mean modifying vendored code, so the simpler fix is used instead: verified
// zero table-name collisions between our schema (all snake_case: posts,
// campaigns, ig_accounts, ...) and OpenReply's (all PascalCase model names:
// User, Automation, InstagramAccount, ...), so they safely share `public`.
// OpenReply (Prisma, many serverless instances, up to 10 connections each) uses Supabase's TRANSACTION pooler
// (port 6543) so it cannot exhaust the session pooler's ~15 slots; verified with interactive transactions and
// parallel/repeated queries. pg-boss and the dashboard need session mode and keep the root DATABASE_URL (5432).
function forOpenReply(url: string): string {
  try {
    const u = new URL(url);
    if (u.hostname.endsWith(".pooler.supabase.com") && u.port !== "6543") u.port = "6543";
    return u.toString();
  } catch {
    return url;
  }
}
const databaseUrl = forOpenReply(required("DATABASE_URL"));

const lines: string[] = [
  "# GENERATED by scripts/sync-openreply-env.ts — do not edit directly.",
  "# Edit the root .env's OPENREPLY_* / META_* values and re-run:",
  "#   npm run sync-openreply-env",
  "",
  "# --- App ---",
  `NEXTAUTH_URL=http://localhost:${port}`,
  `NEXTAUTH_SECRET=${required("OPENREPLY_NEXTAUTH_SECRET")}`,
  `CRON_SECRET=${required("OPENREPLY_CRON_SECRET")}`,
  `ENCRYPTION_KEY=${required("OPENREPLY_ENCRYPTION_KEY")}`,
  "",
  "# --- Database / queue ---",
  `DATABASE_URL=${databaseUrl}`,
  `REDIS_URL=${required("OPENREPLY_REDIS_URL")}`,
  "",
  "# --- Email magic links ---",
  `RESEND_API_KEY=${optional("OPENREPLY_RESEND_API_KEY")}`,
  `EMAIL_FROM=${optional("OPENREPLY_EMAIL_FROM", "OpenReply <login@example.com>")}`,
  ...(optional("OPENREPLY_EMAIL_SERVER") ? [`EMAIL_SERVER=${optional("OPENREPLY_EMAIL_SERVER")}`] : []),
  "",
  "# --- Meta / Instagram (shared Meta app, mapped from root .env) ---",
  `META_GRAPH_API_VERSION=${required("META_GRAPH_VERSION")}`,
  `INSTAGRAM_APP_ID=${required("META_APP_ID")}`,
  `INSTAGRAM_APP_SECRET=${required("META_APP_SECRET")}`,
  `FACEBOOK_APP_SECRET=${optional("OPENREPLY_FACEBOOK_APP_SECRET") || required("META_APP_SECRET")}`,
  `WEBHOOK_VERIFY_TOKEN=${required("META_WEBHOOK_VERIFY_TOKEN")}`,
  ""
];

const outPath = resolve(process.cwd(), "vendor/openreply/.env");
writeFileSync(outPath, lines.join("\n"), "utf-8");
console.log(`Wrote ${outPath} from ${rootEnvPath}`);
